#pragma once
#include <stdint.h>
struct logo { uint16_t w,h,stride; const uint8_t *bits; }; /* e-ink mark: rows msb first, 1 = black */
extern const struct logo logo_large,logo_small; /* 96x96 and 40x40 */
/* HDMI art: palette indices in runs, one byte each (high nibble color, low nibble length-1). */
struct art_runs { uint16_t w,h,colors,bytes; const uint32_t *palette; const uint8_t *runs; };
extern const struct art_runs art_panel,art_header; /* 364x96 overlay panel; 424x72 recovery header */
